W=$HOME/alba-cross-policy-20261101; for e in smolvla openpi; do P=$(ls -d $W/envs/$e/lib/python3*/site-packages/lerobot 2>/dev/null); echo "ENV $e lerobot=$P"; [ -n "$P" ] && { cat $W/envs/$e/lib/python3*/site-packages/lerobot-*.dist-info/direct_url.json 2>/dev/null; echo; ls $P/policies 2>/dev/null | tr "\n" " "; echo; F=$(ls $P/policies/pi05/configuration_pi05.py 2>/dev/null); [ -n "$F" ] && grep -n -E "normalization_mapping|QUANTILE|MEAN_STD|num_inference_steps|num_steps" $F | head; G=$(ls $P/policies/pi05/modeling_pi05.py 2>/dev/null); [ -n "$G" ] && grep -n -E "num_inference_steps|num_steps|for .* in range|while " $G | head -12; }; done; find $HOME -maxdepth 4 -iname "*pi05*" -not -path "*/alba-cross-policy-20261101/*" 2>/dev/null | head